pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a simple ERC20 token to observe transferFrom side effects
        address token = address(0x123);
        address from = address(0x456);
        address to1 = address(0x789);
        address to2 = address(0xabc);
        address to3 = address(0xdef);
        address[] memory tos = new address[](3);
        tos[0] = to1;
        tos[1] = to2;
        tos[2] = to3;
        uint256 v = 100;

        // Since the call executes low-level call with transferFrom selector,
        // we can't easily track token balances. Instead, use a different approach:
        // Deploy a helper contract that logs calls, but per rules we cannot.
        // Alternative: Observe revert behavior - the bug skips first transfer thus
        // any state change tied to first transfer will differ.
        // But the simplest is: the buggy contract only calls 2 times instead of 3.
        // We can't observe that directly without helper.
        // Therefore, we'll craft a scenario where the first call reverts and the
        // whole call still proceeds in buggy version but reverts in reference.
        // However, require(_tos.length > 0) ensures length>0, not runtime revert.
        // To observe difference: deploy a mock token that tracks calls.
        // But per rules we cannot deploy extra contracts.
        // So observe: the buggy loop skips index 0, so if token reverts on index 0,
        // reference will revert while buggy succeeds.
        // We'll use a pre-funded account to trigger revert via low-level call.
        // Actually simpler: use address(0) as first tos, which causes revert on
        // transferFrom because address(0) is invalid.
        // Reference calls transferFrom(from, address(0), v) -> revert -> whole tx reverts.
        // Buggy skips first, so no revert, tx succeeds.
        tos[0] = address(0);
        tos[1] = to2;
        tos[2] = to3;

        bool ok;
        try c.transfer(from, token, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference (correct) reverts because first call to address(0) reverts.
        // Buggy (skip first) does not revert and returns true.
        // So for the reference contract, ok = false; for buggy, ok = true.
        // Assert that ok is false, which holds for reference but fails for buggy.
        assertTrue(!ok, "Expected revert due to invalid first recipient");
    }
}

