pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Create a dummy target that will revert on any call
        address dummy = address(0xdead);
        address from = address(this);
        address[] memory tos = new address[](1);
        tos[0] = dummy;
        // The reference contract will make a call to dummy (which reverts), so transfer reverts
        // The buggy contract (loop starts at 1) will not make any call because _tos.length == 1, so transfer succeeds
        bool ok;
        try c.transfer(from, dummy, tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C reverts => ok == false; buggy M does not revert => ok == true
        assertTrue(!ok, "Expected revert for reference contract");
    }
}

