pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a minimal token that records the last caller of transferFrom
        Token token = new Token();
        address alice = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = alice;
        // Call transfer with from=alice, caddress = token
        c.transfer(alice, address(token), tos, 100);
        // The reference should have called transferFrom(alice, alice, 100), so lastCaller = alice
        // The buggy version calls transferFrom(address(0), alice, 100), so lastCaller = address(0)
        assertTrue(token.lastCaller() == alice, "lastCaller should be alice in correct version");
    }
}

contract Token {
    address public lastCaller;
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        lastCaller = from;
        return true;
    }
}

