pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // 1. Set up scenario: create a token contract that implements transferFrom
        // We use a simple mock token that records the last transfer value
        // Deploy a minimal token contract that stores the last transferred value
        TokenMock token = new TokenMock();
        address from = address(0x1234);
        address[] memory tos = new address[](2);
        tos[0] = address(0x5678);
        tos[1] = address(0x9abc);
        uint256 v = 5;

        // 2. Execute the transfer call
        c.transfer(from, address(token), tos, v);

        // 3. Assert: the correct contract transferred v (5) to each recipient
        // The bug transferred 0. We check token's stored value (the last transfer) should be 5 in reference, 0 in bug.
        assertTrue(token.lastValue() == v, "Should transfer the specified amount");
    }
}

contract TokenMock {
    uint256 public lastValue;

    function transferFrom(address, address, uint256 value) external returns (bool) {
        lastValue = value;
        return true;
    }
}
